local ActivatorUtilities = require(script.Parent)
local InstanceManager = require(script.Parent.Parent.Parent.InstancePathManager)
local UnitTestHostBuilderFactory =
	require(game.ReplicatedStorage.Packages.TangSeng.Core.Misc.UnitTestHostBuilderFactory)

return function()
	describe("ActivatorUtilities", function()
		it("should create instance from string type", function()
			local builder = UnitTestHostBuilderFactory()
			local serviceProvider = builder:Build().Services
			local path = InstanceManager.GetPathAndCache(script.Parent.TestService)

			local result = ActivatorUtilities.CreateInstance(serviceProvider, path, "success")
			expect(result.testValue).to.equal("success")
		end)

		it("should create instance from ModuleScript", function()
			local builder = UnitTestHostBuilderFactory()
			local serviceProvider = builder:Build().Services
			local result = ActivatorUtilities.CreateInstance(serviceProvider, script.Parent.TestService, "success")
			expect(result).to.be.ok()
			expect(result.ServiceProvider).to.be.ok()
			expect(result.testValue).to.equal("success")
		end)

		-- it("should throw error for invalid type", function()
		-- 	local builder = UnitTestHostBuilderFactory()
		-- 	local serviceProvider = builder:Build().Services

		-- 	expect(function()
		-- 		ActivatorUtilities.CreateInstance(serviceProvider, 123)
		-- 	end).to.throw()
		-- end)
	end)
end
